"""Original study material. No source paragraphs or published exercises are copied.

Each record: stable key | track | title | explanation | worked scenario | practice |
worked answer | checkpoint question | correct answer | two misconceptions.
Reasoning exercises are deliberately separate from executable code.
"""
TOPICS = r'''
'''

def records():
    result=[]
    for line in TOPICS.strip().splitlines():
        if not line.strip(): continue
        fields=line.split('|')
        if len(fields)!=11: raise ValueError((fields[0],len(fields)))
        key,track,title,body,worked,challenge,solution,question,correct,*wrong=fields
        result.append(dict(key=key,trackID=track,title=title,body=[body],workedExample=worked,challenge=challenge,solution=solution,question=question,options=[correct,*wrong],answerIndex=0,explanation=correct,recall=[[question,correct+' '+body],[challenge,solution]]))
    return result

